    $('#view').innerHTML = `<h1>문의 <span class="muted small">${rows.length}건</span></h1><div class="tbl"><table><thead><tr><th>접수</th><th>구분</th><th>성함·연락처</th><th>종목·예산</th><th>내용</th><th>유입</th><th>상태</th><th>메모</th></tr></thead><tbody>${rows.map(r => `<tr><td class="small">${dt(r.created_at)}</td><td>${K[r.kind] || r.kind}<br><span class="small muted">${CAT[r.category] || LCAT[r.category] || r.category || ''}</span></td><td><b>${esc(r.name)}</b><br><a href="tel:${esc(r.phone)}">${esc(r.phone)}</a>${r.email ? '<br><span class="small">' + esc(r.email) + '</span>' : ''}</td><td class="small">${esc(r.item || '')}<br>${esc(r.budget || '')}</td><td class="small" style="max-width:260px">${esc(r.message || '')}</td><td class="small">${r.src_source ? `<b>${esc(r.src_source)}</b>${r.src_keyword ? '<br>검색어 ' + esc(r.src_keyword) : ''}${r.src_campaign ? '<br>캠페인 ' + esc(r.src_campaign) : ''}<br><span class="muted">처음 ${esc(decodeURIComponent(r.src_landing || ''))}</span>${r.session_id ? ` <a href="#" data-trail="${esc(r.session_id)}">경로</a>` : ''}` : `<span class="muted">${esc((r.referrer || '').replace(/^https?:\/\/[^/]+/, '') || '기록 없음')}</span>`}</td><td><select data-st="${r.id}" style="width:auto"><option value="new" ${r.status === 'new' ? 'selected' : ''}>신규</option><option value="contacted" ${r.status === 'contacted' ? 'selected' : ''}>연락함</option><option value="done" ${r.status === 'done' ? 'selected' : ''}>완료</option></select></td><td><input data-memo="${r.id}" value="${esc(r.memo || '')}" placeholder="메모 후 Enter" style="min-width:140px"></td></tr>`).join('') || '<tr><td colspan="8" class="muted">없음</td></tr>'}</tbody></table></div>`;
    const save = async (id) => { const st = $(`[data-st="${id}"]`).value, memo = $(`[data-memo="${id}"]`).value; await api('/inquiries/' + id, { method: 'POST', body: { status: st, memo } }); toast('저장'); };
    $$('[data-trail]').forEach(a => a.onclick = async (e) => { e.preventDefault(); try { const t = await api('/inflow/session/' + a.dataset.trail); const N = { view: '페이지 열람', tel: '전화 클릭', kakao: '카카오톡 문의 클릭', inquiry: '문의 접수', outbound: '외부 채널 클릭', form: '문의 폼 입력 시작' }; modal(`<h2>문의 고객의 방문 경로</h2><p><b>${esc(t.visit.label)}</b> · ${esc(t.visit.source)}${t.visit.keyword ? ' · 검색어 ' + esc(t.visit.keyword) : ''}</p><table><thead><tr><th>시각</th><th>행동</th><th>페이지</th></tr></thead><tbody>${t.events.map(x => `<tr><td class="small">${dt(x.ts)}</td><td>${esc(N[x.type] || x.type)} ${esc(x.label || '')}</td><td class="small">${esc(decodeURIComponent(x.path || ''))}</td></tr>`).join('')}</tbody></table>`); } catch (err) { toast(err.message, true); } });
