    const build = () => { const url = $('#utmUrl').value.trim(); const camp = $('#utmCamp').value.trim(); if (!url || !camp) { $('#utmOut').value = ''; return; } const [src, med] = $('#utmSrc').value.split('|'); try { const u = new URL(url); u.searchParams.set('utm_source', src); u.searchParams.set('utm_medium', med); u.searchParams.set('utm_campaign', camp); const c = $('#utmCont').value.trim(); if (c) u.searchParams.set('utm_content', c); $('#utmOut').value = u.toString(); } catch (_) { $('#utmOut').value = ''; } };
    ['utmUrl', 'utmSrc', 'utmCamp', 'utmCont'].forEach(id => { $('#' + id).oninput = build; $('#' + id).onchange = build; });
